def dump(name,data): (OUT/name).write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')

def broad():
 rows=[]; oid=1
 for cohort in range(6):
  for idx,(name,job,arch,query) in enumerate(SEEDS):
   lang,market,fmt,price,elig=ROUTES[(idx+cohort)%len(ROUTES)]
   rid=f'RN7-{oid:03d}'
   if rid=='RN7-001': lang,market,fmt,price,elig=ROUTES[0]
   if rid in DEEP_IDS and elig not in {'SUPPORTED','PAPERBACK_ONLY'}: lang,market,fmt,price,elig=ROUTES[1]
   path='COMMERCIAL_INTENT' if idx<45 else 'EXPLORATORY_WEAK_PRIOR'
   trigger=3+(idx%3) if path=='COMMERCIAL_INTENT' else 1+(idx%3)
   value=3+((idx*2)%3) if path=='COMMERCIAL_INTENT' else 2+((idx*2)%3)
   natural=3+((idx*3)%3) if path=='COMMERCIAL_INTENT' else 2+((idx*3)%3)
   wtp=3+((idx*5)%3) if path=='COMMERCIAL_INTENT' else 1+((idx*5)%4)
   ci=round((trigger+value+natural+wtp)/4,1)
   rows.append({'id':rid,'working_product':name,'language':lang,'primary_marketplace':market,'buyer':'specific buyer facing the named event','trigger':job,'buyer_job':job,'query_cluster':query,'product_architecture':arch,'primary_format':fmt,'format_eligibility':elig,'price_band':price,'generation_path':path,'source_origin':['OFFICIAL_COMPLEXITY','SEARCH_QUERY','COMMUNITY_REDDIT','MARKETPLACE_GAP'][idx%4],'experimental_signals':{'purchase_trigger_strength':trigger,'value_of_solving':value,'time_to_need':'NOW_DAYS' if trigger>=5 else 'WEEKS' if trigger==4 else 'ONGOING','book_purchase_naturalness':natural,'wtp_proxy_strength':wtp,'commercial_intent_confidence':ci,'evidence_label':'INFERRED_AT_BROAD_SCREEN'},'decision':'DEEP_SCAN' if rid in DEEP_IDS else 'REJECT','rejection_reason':None if rid in DEEP_IDS else 'lower evidence-adjusted priority; experimental signals are not hard gates'})
   oid+=1
 assert len(rows)==360 and sum(r['generation_path']=='EXPLORATORY_WEAK_PRIOR' for r in rows)==90
 return rows

