 dump('broad-opportunities.json',{'schema_version':'radar-native-7-broad/v1','run_id':'RN7','strategy':'candidate-generation-v2','observed_at':DATE,'count':len(rows),'generation_mix':{'commercial_intent':270,'exploratory_weak_prior':90},'opportunities':rows})
